import{_ as e,o as a,c as r,a2 as n}from"./chunks/framework.DDY-poMm.js";const p=JSON.parse('{"title":"Wealth Products","description":"","frontmatter":{},"headers":[],"relativePath":"guide/wealth.md","filePath":"guide/wealth.md","lastUpdated":1790683574000}'),o={name:"guide/wealth.md"};function s(i,t,d,l,u,c){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="wealth-products" tabindex="-1">Wealth Products <a class="header-anchor" href="#wealth-products" aria-label="Permalink to &quot;Wealth Products&quot;">​</a></h1><p>The platform offers three value-added products — wealth management, staking and assisted lending — plus new-coin subscription. Whether each is open to users is controlled by &quot;Basic Configuration → Product configuration&quot;; settlement methods are set on the &quot;Product configuration&quot; page in the admin console.</p><h2 id="wealth-management" tabindex="-1">Wealth management <a class="header-anchor" href="#wealth-management" aria-label="Permalink to &quot;Wealth management&quot;">​</a></h2><p>Asset management products that accrue interest by term. The user side has <strong>three sections</strong>: <strong>Standard / Members / Enhanced Yield</strong>, chosen when the product is created. Member-section products can have a VIP tier threshold — users below the tier can see them but cannot buy.</p><h3 id="product-configuration-wealth-products-in-the-admin-console" tabindex="-1">Product configuration (&quot;Wealth Products&quot; in the admin console) <a class="header-anchor" href="#product-configuration-wealth-products-in-the-admin-console" aria-label="Permalink to &quot;Product configuration (&quot;Wealth Products&quot; in the admin console)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Title / icon / coin / category</td><td>Name, icon, currency and section shown to users</td></tr><tr><td>Days</td><td>Lock-up period, settled at maturity</td></tr><tr><td>Min / max daily rate (%)</td><td>The yield range shown to users; actual interest follows the settlement rules in the admin console</td></tr><tr><td>Early-redemption rate (%)</td><td>Penalty deducted at this rate when a user redeems early; the rest is refunded</td></tr><tr><td>Min / max amount</td><td>Range for a single subscription</td></tr><tr><td>Purchase limit</td><td>How many times one user can buy; <strong>0 means unlimited</strong></td></tr><tr><td>VIP tier</td><td>Purchase threshold</td></tr><tr><td>Hot / enabled / order</td><td>Badge, listing status and display order on the user side</td></tr></tbody></table><h3 id="orders-and-earnings" tabindex="-1">Orders and earnings <a class="header-anchor" href="#orders-and-earnings" aria-label="Permalink to &quot;Orders and earnings&quot;">​</a></h3><ul><li>&quot;Wealth Orders&quot; shows each subscription&#39;s product, amount, creation and maturity time and status; eligible orders can be <strong>redeemed</strong> (with order number confirmation)</li><li>The user&#39;s &quot;My Wealth&quot; shows <strong>earned today</strong> (only earnings paid out today) and <strong>total earnings</strong> (all payouts to date) — two different measures, not the same number</li><li>Settlement method is chosen under &quot;Product configuration → Wealth settlement type&quot;: <strong>daily</strong>, <strong>at maturity</strong>, or <strong>every N days</strong> (between 1 and 28)</li></ul><h2 id="staking" tabindex="-1">Staking <a class="header-anchor" href="#staking" aria-label="Permalink to &quot;Staking&quot;">​</a></h2><p>Users lock assets to earn rewards. Products are maintained under &quot;Mining Products&quot; in the admin console, with the same fields as wealth products (days, rate range, amounts, purchase limit, etc.), plus a &quot;show on front end&quot; switch.</p><ul><li><strong>Per-user staking limits</strong>: you can set the purchase count for a product for an <strong>individual user</strong> (e.g. lifting the limit for a test account); add it from the corresponding product on the &quot;Mining Products&quot; page</li><li>&quot;Staking Orders&quot; shows each stake&#39;s project, accumulated earnings, maturity and status</li><li>Settlement method is set under &quot;Product configuration → Staking settlement type&quot;</li></ul><h2 id="assisted-lending" tabindex="-1">Assisted lending <a class="header-anchor" href="#assisted-lending" aria-label="Permalink to &quot;Assisted lending&quot;">​</a></h2><p>A lending product. Limits, terms and rates are configured in the admin console, and applications require admin review.</p><h2 id="token-subscription-ipo" tabindex="-1">Token subscription (IPO) <a class="header-anchor" href="#token-subscription-ipo" aria-label="Permalink to &quot;Token subscription (IPO)&quot;">​</a></h2><p>A new-coin subscription product. Projects are created under &quot;Coin Issuance&quot; in the admin console and move through &quot;Preparing → Subscription → Approval → In progress → Issued&quot;:</p><ol><li><strong>Preparing</strong>: fill in the issuance information (text and images); not yet visible to users</li><li><strong>Open for subscription</strong>: users can submit subscription requests (see &quot;Subscription Orders&quot;)</li><li><strong>Approval</strong>: operators approve or reject each request under &quot;New Coin Subscriptions&quot;</li><li><strong>Issued</strong>: the coin is officially issued, and approved users receive their allocation</li></ol><div class="warning custom-block"><p class="custom-block-title">Configuration reminder</p><p>When creating a subscription project, <strong>&quot;Purchase limit&quot; must be filled in</strong>; leaving it empty may cause order errors on the user side.</p></div><hr><h2 id="general-operating-tips" tabindex="-1">General operating tips <a class="header-anchor" href="#general-operating-tips" aria-label="Permalink to &quot;General operating tips&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Earnings settlement</p><p>Earnings from wealth products are settled and paid out by the system&#39;s scheduled jobs, with <strong>idempotency control</strong> so the same period is never paid twice. If a period&#39;s earnings seem missing, first check that product&#39;s status and order records in the admin console, then contact your technical team — <strong>do not pay it manually with a balance adjustment</strong>, as that bypasses the ledger logic and makes later reconciliation harder.</p></div><div class="warning custom-block"><p class="custom-block-title">Changing products already in progress</p><p>Once <strong>users have joined a product</strong>, do not change core parameters such as its rate or term. Participating users calculated their expected earnings on the original parameters, and changes midway cause complaints. To adjust, delist the old product and create a new one.</p></div><div class="danger custom-block"><p class="custom-block-title">Amounts and limits</p><p>Fill in all amount ranges and per-user limits when configuring a product. Empty limit fields may cause errors when placing orders.</p></div>',22)])])}const g=e(o,[["render",s]]);export{p as __pageData,g as default};
